package net.officefloor.hq.app.history;

import java.sql.Connection;
import java.sql.Date;
import java.sql.SQLException;
import java.sql.Savepoint;
import java.time.LocalDate;
import java.util.List;
import java.util.function.Function;
import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DataSourceUtils;
import org.springframework.jdbc.datasource.SingleConnectionDataSource;
import org.springframework.stereotype.Repository;

/**
 * A sheet as it stood at the end of a date. As the sheet's today moves on, the sheet is snapshotted (schema hist): the
 * snapshot holds every change made while its today was the old one or earlier, and none made later. Read as of a date,
 * the latest snapshot taken as the today moved on from that date or before it to a later one is laid out as the live
 * tables (schema asof), its today standing at that date, and read by the app's own repositories.
 */
@Repository
public class SheetHistory {

    /** The tables the screen reads (a statement's figures among them), parents before children. */
    private static final List<String> TABLES = List.of("sheet", "person", "person_grade", "person_hold",
            "person_patron", "person_alias", "person_watch", "statement", "claim", "claim_log", "claim_lock", "rate", "sheet_setting",
            "sheet_setting_from", "period", "period_person_total", "sheet_role", "sheet_delegation", "holiday", "claim_tag", "void_reason", "claim_comment", "claim_template");

    private final JdbcTemplate jdbc;

    private final DataSource dataSource;

    public SheetHistory(JdbcTemplate jdbc, DataSource dataSource) {
        this.jdbc = jdbc;
        this.dataSource = dataSource;
    }

    /** Snapshot the sheet as its today moves on from {@code through} to the later {@code until}. */
    public void snapshot(String sheetId, LocalDate through, LocalDate until) {
        long id = jdbc.queryForObject("SELECT id FROM FINAL TABLE (INSERT INTO sheet_snapshot (sheet_id, through, until)"
                + " VALUES (?, ?, ?))", Long.class, sheetId, Date.valueOf(through), Date.valueOf(until));
        for (String table : TABLES) {
            String columns = columns(jdbc, table);
            jdbc.update("INSERT INTO hist." + table + " (" + columns + ", snapshot_id) SELECT " + columns + ", ? FROM "
                    + "public." + table + " WHERE " + ofSheet(table, "public"), id, sheetId);
        }
    }

    /** The snapshot holding the sheet as it stood at the end of the date; null when its today never moved on past it. */
    public Long snapshotAsOf(String sheetId, LocalDate on) {
        return jdbc.query("SELECT id FROM sheet_snapshot WHERE sheet_id = ? AND through <= ? AND until > ?"
                + " ORDER BY id DESC LIMIT 1", (rs, n) -> rs.getLong(1), sheetId, Date.valueOf(on), Date.valueOf(on))
                .stream().findFirst().orElse(null);
    }

    /**
     * Read the snapshot, its today standing at {@code on}: {@code reader} is given a JdbcTemplate over the snapshot laid
     * out as the live tables, for the app's repositories to read it as they read the live sheet.
     */
-- The sheet's claim templates: a name (stored trimmed, at most once on its sheet: saving a name again replaces that
-- template), an amount the claim form would accept and a note. A claim made from one copies its amount and note then.
CREATE TABLE claim_template (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200)   NOT NULL REFERENCES sheet (id),
    name     VARCHAR(200)   NOT NULL,
    amount   DECIMAL(14, 2) NOT NULL,
    note     VARCHAR(1000)  NOT NULL
);
CREATE UNIQUE INDEX claim_template_sheet_name ON claim_template (sheet_id, name);

-- Snapshotted with the rest of the screen (see V40, V41).
CREATE TABLE hist.claim_template AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM claim_template t WHERE FALSE;
CREATE INDEX hist_claim_template_snapshot ON hist.claim_template (snapshot_id);
CREATE TABLE asof.claim_template AS SELECT * FROM claim_template WHERE FALSE;
package net.officefloor.hq.app.person;

import java.util.stream.Stream;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Names another person on the sheet as the person's patron; refuses the person themselves and a patron they have already. */
public class AddPatron {
    public void add(@Val PatronInput input, @Val Person person, PersonRepository repository, Out<PatronAdded> added)
            throws BadRequestException {
        Person patron = repository.find(person.getSheetId(), input.patronId());
        if (patron == null) {
            throw new BadRequestException("No such person on this sheet");
        }
        if (patron.getId() == person.getId()) {
            throw new BadRequestException("A person cannot be their own patron");
        }
        if (!repository.addPatron(person.getId(), patron.getId())) {
            throw new BadRequestException(patron.getName() + " is already a patron; reload the sheet");
        }
        person.setPatrons(Stream.concat(person.getPatrons().stream(), Stream.of(patron.getName())).sorted().toList());
        added.set(new PatronAdded(patron));
    }
}
